import {contains} from './geometry.mjs';
export function createLetterRouter(letter,mask,w,h,clearance=3,cell=2){
 const minx=Math.max(0,Math.floor(Math.min(...letter.points.map(p=>p[0])))),miny=Math.max(0,Math.floor(Math.min(...letter.points.map(p=>p[1])))),maxx=Math.min(w,Math.ceil(Math.max(...letter.points.map(p=>p[0])))),maxy=Math.min(h,Math.ceil(Math.max(...letter.points.map(p=>p[1]))));
 const nx=Math.ceil((maxx-minx)/cell),ny=Math.ceil((maxy-miny)/cell),allowed=new Uint8Array(nx*ny);
 const inside=(x,y)=>x>=0&&y>=0&&x<w&&y<h&&mask[Math.floor(y)*w+Math.floor(x)]&&contains(letter.points,[x,y])&&!letter.holes.some(p=>contains(p,[x,y]));
 const safe=(x,y)=>inside(x,y)&&[[clearance,0],[-clearance,0],[0,clearance],[0,-clearance],[clearance*.7,clearance*.7],[-clearance*.7,clearance*.7],[clearance*.7,-clearance*.7],[-clearance*.7,-clearance*.7]].every(([dx,dy])=>inside(x+dx,y+dy));
 const coord=i=>[minx+(i%nx+.5)*cell,miny+(Math.floor(i/nx)+.5)*cell];
 for(let i=0;i<allowed.length;i++){const p=coord(i);allowed[i]=safe(...p)?1:0;}
 const segmentSafe=(a,b)=>{const count=Math.max(1,Math.ceil(Math.hypot(b[0]-a[0],b[1]-a[1])/.5));for(let i=0;i<=count;i++){const t=i/count;if(!safe(a[0]*(1-t)+b[0]*t,a[1]*(1-t)+b[1]*t))return false;}return true;};
 const nearest=p=>{let best=-1,distance=Infinity;const cx=Math.floor((p[0]-minx)/cell),cy=Math.floor((p[1]-miny)/cell);for(let dy=-3;dy<=3;dy++)for(let dx=-3;dx<=3;dx++){const x=cx+dx,y=cy+dy,i=y*nx+x;if(x<0||y<0||x>=nx||y>=ny||!allowed[i])continue;const q=coord(i),d=Math.hypot(q[0]-p[0],q[1]-p[1]);if(d<distance&&segmentSafe(p,q)){distance=d;best=i;}}return best;};
 class Heap{constructor(){this.a=[];}push(item){const a=this.a;let i=a.push(item)-1;while(i){const p=(i-1)>>1;if(a[p][1]<=item[1])break;a[i]=a[p];i=p;}a[i]=item;}pop(){const a=this.a,top=a[0],last=a.pop();if(a.length){let i=0;while(i*2+1<a.length){let c=i*2+1;if(c+1<a.length&&a[c+1][1]<a[c][1])c++;if(a[c][1]>=last[1])break;a[i]=a[c];i=c;}a[i]=last;}return top;}}
 function route(a,b){if(segmentSafe(a,b))return [a,b];const start=nearest(a),end=nearest(b);if(start<0||end<0)return null;const g=new Float32Array(nx*ny);g.fill(Infinity);const previous=new Int32Array(nx*ny);previous.fill(-1);const closed=new Uint8Array(nx*ny),heap=new Heap();const heuristic=i=>{const dx=Math.abs(i%nx-end%nx),dy=Math.abs(Math.floor(i/nx)-Math.floor(end/nx));return Math.max(dx,dy)+(Math.SQRT2-1)*Math.min(dx,dy);};g[start]=0;heap.push([start,heuristic(start)]);let found=false;
  while(heap.a.length){const [i]=heap.pop();if(closed[i])continue;if(i===end){found=true;break;}closed[i]=1;const x=i%nx,y=Math.floor(i/nx);for(let dy=-1;dy<=1;dy++)for(let dx=-1;dx<=1;dx++){if(!dx&&!dy)continue;const xx=x+dx,yy=y+dy,j=yy*nx+xx;if(xx<0||yy<0||xx>=nx||yy>=ny||!allowed[j]||closed[j])continue;if(dx&&dy&&(!allowed[y*nx+xx]||!allowed[yy*nx+x]))continue;const cost=g[i]+(dx&&dy?Math.SQRT2:1);if(cost<g[j]){g[j]=cost;previous[j]=i;heap.push([j,cost+heuristic(j)]);}}}
  if(!found)return null;const path=[];for(let i=end;i>=0;i=previous[i]){path.push(coord(i));if(i===start)break;}path.reverse();path.unshift(a);path.push(b);const clean=[path[0]];let i=0;while(i<path.length-1){let j=path.length-1;while(j>i+1&&!segmentSafe(path[i],path[j]))j--;if(!segmentSafe(path[i],path[j]))return null;clean.push(path[j]);i=j;}return clean;
 }
 return {route,inside,safe,segmentSafe};
}

export function distanceField(mask,w,h){const d=new Float32Array(w*h);for(let i=0;i<d.length;i++)d[i]=mask[i]?1e6:0;const diagonal=Math.SQRT2;for(let y=0;y<h;y++)for(let x=0;x<w;x++){const i=y*w+x;if(!mask[i])continue;d[i]=Math.min(d[i],x?d[i-1]+1:1,y?d[i-w]+1:1,x&&y?d[i-w-1]+diagonal:1,y&&x<w-1?d[i-w+1]+diagonal:1);}for(let y=h-1;y>=0;y--)for(let x=w-1;x>=0;x--){const i=y*w+x;if(!mask[i])continue;d[i]=Math.min(d[i],x<w-1?d[i+1]+1:1,y<h-1?d[i+w]+1:1,x<w-1&&y<h-1?d[i+w+1]+diagonal:1,x&&y<h-1?d[i+w-1]+diagonal:1);}return d;}
export function mountingPoints(letter,dist,w,h){const xs=letter.points.map(p=>p[0]),ys=letter.points.map(p=>p[1]),minx=Math.max(0,Math.floor(Math.min(...xs))),maxx=Math.min(w-1,Math.ceil(Math.max(...xs))),miny=Math.max(0,Math.floor(Math.min(...ys))),maxy=Math.min(h-1,Math.ceil(Math.max(...ys))),axis=maxy-miny>maxx-minx?1:0,step=Math.max(1,Math.floor(Math.max(maxx-minx,maxy-miny)/60));const candidates=[];for(let y=miny;y<=maxy;y+=step)for(let x=minx;x<=maxx;x+=step){const clearance=dist[y*w+x];if(clearance>1.5&&contains(letter.points,[x+.5,y+.5])&&!letter.holes.some(p=>contains(p,[x+.5,y+.5])))candidates.push({point:[x+.5,y+.5],clearance});}if(candidates.length<2)return candidates;const low=Math.min(...candidates.map(p=>p.point[axis])),high=Math.max(...candidates.map(p=>p.point[axis])),range=high-low;const score=(p,target)=>p.clearance-2*Math.abs(p.point[axis]-target);const a=candidates.reduce((a,b)=>score(a,low+range*.23)>score(b,low+range*.23)?a:b);const far=candidates.filter(p=>Math.hypot(p.point[0]-a.point[0],p.point[1]-a.point[1])>Math.max(2,a.clearance));if(!far.length)return [a];const b=far.reduce((a,b)=>score(a,low+range*.77)>score(b,low+range*.77)?a:b);return [a,b];}
